 q=c.cursor();q.execute("select o.ORDER_ID,o.WARE_ID,l.LINE_NUMBER,l.ARTICUL,l.PLANNED_QTY,l.BASE_UOM,settings.COMPANY_PREFIX from RRL_SAP_SUPPLY_ORDER o join RRL_PRIHOD_NAKLAD h on h.ID=o.NAKLAD_ID join RRL_SAP_SUPPLY_LINE l on l.ORDER_ID=o.ORDER_ID join RRL_RECEIPT_WARE_SETTINGS settings on settings.WARE_ID=o.WARE_ID where o.CLOSED_AT is null and nvl(h.CONDITION,0)=0 and settings.COMPANY_PREFIX is not null order by o.ORDER_ID desc fetch first 3 rows only");print(q.fetchall())
